L5_1.m_VoiceFileName = "AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE_IN_CUTSCENE_3"
L5_1.m_Talk_KOREA = "여인은 제 목을 노리는 커다란 범과 마주하고 있으나, 내가 아무리 손을 뻗어도 닿지 않아."
L5_1.m_fTalkTime = 0.03
L5_1.m_bTalkCenterFadeIn = true
L5_1.m_Talk_JPN = "その女性は己の首を狙う大きな虎と向かい合っているのだが、某がいくら手を伸ばそうとも、まったく届かなくでな。"
L5_1.m_Talk_ENG = "A great tiger stands before her, poised for her throat, yet no matter how far I reach, I can't touch her."
L5_1.m_Talk_TWN = "女人與虎視眈眈的老虎搏鬥，但無論我怎麼伸手，就是觸不到她。"
L5_1.m_Talk_SCN = "女子正面对着一只对我虎视眈眈老虎，但无论我怎么伸手都无法触及。"
L5_1.m_Talk_DEU = "A great tiger stands before her, poised for her throat, yet no matter how far I reach, I can't touch her."
L5_1.m_Talk_FRA = "A great tiger stands before her, poised for her throat, yet no matter how far I reach, I can't touch her."
