L7_1.m_Talk_KOREA = "그녀가 뒤를 돌아 나를 바라볼 즈음이면, 만개하듯 번지는 핏자국에 눈앞이 붉게 질려."
L7_1.m_fTalkTime = 0.03
L7_1.m_bTalkCenterFadeIn = true
L7_1.m_Talk_JPN = "その女性が振り返り某に目を向けると、飛び散る血しぶきに視野が埋め尽くされる。"
L7_1.m_Talk_ENG = "By the time she turns and looks my way, my vision is already stained red with blood spreading like petals."
L7_1.m_Talk_TWN = "當她回頭望向我時，眼前便被大片的血跡給染得一片猩紅。"
L7_1.m_Talk_SCN = "当她转过身来望向我的时候，眼前被如同盛开般扩散的血迹染得通红。"
L7_1.m_Talk_DEU = "By the time she turns and looks my way, my vision is already stained red with blood spreading like petals."
L7_1.m_Talk_FRA = "By the time she turns and looks my way, my vision is already stained red with blood spreading like petals."
