L9_1.m_VoiceFileName = "AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE_IN_CUTSCENE_5"
L9_1.m_Talk_KOREA = "그렇게 꿈에서 깨어나면, 뜻 모를 공허함이 새벽 안개처럼 밀려들어 숨통을 갑갑하게 조여오지."
L9_1.m_fTalkTime = 0.03
L9_1.m_bTalkCenterFadeIn = true
L9_1.m_Talk_JPN = "そうやって夢から覚めると、訳の分からぬ虚しさが夜明けの霧のごとく押し寄せ、息が苦しくなるのだ。"
L9_1.m_Talk_ENG = "And when I wake, that nameless emptiness creeps in like the dawn mist, pressing down on my chest."
L9_1.m_Talk_TWN = "當我從夢裡驚醒後，一股莫名的空虛感如早晨的濃霧般襲來，緊緊地掐住我的喉嚨。"
L9_1.m_Talk_SCN = "从梦中醒来时，那种莫名的空虚感如同清晨的雾气般袭来，让人感到窒息。"
L9_1.m_Talk_DEU = "And when I wake, that nameless emptiness creeps in like the dawn mist, pressing down on my chest."
L9_1.m_Talk_FRA = "And when I wake, that nameless emptiness creeps in like the dawn mist, pressing down on my chest."
