L12_1.m_VoiceFileName = "AB_UI_UNIT_VOICE_NKM_UNIT_ATELIER_C_TIMEBLADE_IN_CUTSCENE_6"
L12_1.m_Talk_KOREA = "그 차오르는 갑갑함을 못 이겨 꼭두새벽의 거리를 내달리지만 변하는 건 없어."
L12_1.m_fTalkTime = 0.03
L12_1.m_bTalkCenterFadeIn = true
L12_1.m_Talk_JPN = "湧き上がるもどかしさに耐えきれず、早朝の街をがむしゃらに走っても、変わるものは何もない。"
L12_1.m_Talk_ENG = "To shake it off, I run through the streets before sunrise, but nothing ever changes."
L12_1.m_Talk_TWN = "我無法忍受這股窒息感，於是在大清早地奪門而出，但卻沒有任何改變。"
L12_1.m_Talk_SCN = "我无法忍受那逐渐升起的压抑感，纵然在黎明时分奔跑于街道上，却没有任何作用。"
L12_1.m_Talk_DEU = "To shake it off, I run through the streets before sunrise, but nothing ever changes."
L12_1.m_Talk_FRA = "To shake it off, I run through the streets before sunrise, but nothing ever changes."
