L15_1.m_Talk_KOREA = "다음 날도, 또 그 다음 날도 같은 꿈을 꾸리란 것을… 나는 알고 있기 때문에."
L15_1.m_fTalkTime = 0.03
L15_1.m_bTalkCenterFadeIn = true
