L12_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "기술과 발전의 도시, 챔버에 터를 잡은 지도 1년이란 시간이 흘렀어."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "技術と発展の都市、チェンバーに定着してから、早1年。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "It's been a year since I settled here in Chamber, the city of progress and invention."
L12_1.m_Talk_ENG = L13_1
L13_1 = "落腳在強巴這座以科技與進步為名的城市，已經過了一年。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "在技术与发展的城市——在会议室扎根已经一年了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "It's been a year since I settled here in Chamber, the city of progress and invention."
L12_1.m_Talk_DEU = L13_1
L13_1 = "It's been a year since I settled here in Chamber, the city of progress and invention."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP14_ACT1_PROLOGUE@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 625
L13_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "침식을 딛고 미래를 지어 올린다 라는 그 어구가 마음에 들더군."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "「侵食を乗り越えて未来を築き上げる」というスローガンが気に入ったのでな。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Their motto, \"Build the future atop Corruption's ruins,\" rather appealed to me."
L13_1.m_Talk_ENG = L14_1
L14_1 = "踩著侵蝕築起未來這句標語，讓我頗為欣賞。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "我很喜欢那句“踏过侵蚀，构建未来”。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Their motto, \"Build the future atop Corruption's ruins,\" rather appealed to me."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Their motto, \"Build the future atop Corruption's ruins,\" rather appealed to me."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP14_ACT1_PROLOGUE@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 625
L14_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "그래서 이곳을 더 살기 좋은 곳으로 만들기 위해 1년 동안 다분히 노력했네."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "それゆえ、この街をより良くすべく、この1年間惜しみなく努力してきた。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "So I gave my best this past year, hoping to make this place a little better."
L14_1.m_Talk_ENG = L15_1
L15_1 = "所以這一年來，我竭力讓這裡變得更美好。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "所以我努力了一年，为了让这里变得更适合居住。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "So I gave my best this past year, hoping to make this place a little better."
L14_1.m_Talk_DEU = L15_1
L15_1 = "So I gave my best this past year, hoping to make this place a little better."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP14_ACT1_PROLOGUE@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 625
L15_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "가끔 멀리 고향 생각이 나곤 했지만, 다 지난 일이라 생각하고 묻어둔 채로 말이야."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "時折ぼんやり故郷を思い出すことはあったが、もう過ぎたことだと蓋をして。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Now and then, my mind would drift back home, but I told myself that was all behind me."
L15_1.m_Talk_ENG = L16_1
L16_1 = "偶爾會想起遙遠的故鄉，但也早已將那段往事深埋。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "有时会想起遥远的故乡，但我认为那都是过去的事，就埋藏在心底了。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Now and then, my mind would drift back home, but I told myself that was all behind me."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Now and then, my mind would drift back home, but I told myself that was all behind me."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
