L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "RESEARCHER_NPC_NULL_BALE"
L35_1.m_CharStrID = L36_1
L36_1 = "오늘은 여러 모로 정말 기념비적인 날이지? 마침 회사에 들어온 지 정확히 1년이잖아?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "今日は色んな意味で記念すべき日だよね？　入社してちょうど1年になる日だし。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Quite a milestone, isn't it? It's exactly one year since you joined the company."
L35_1.m_Talk_ENG = L36_1
L36_1 = "今天是特別的一天，不只是你加入公司滿一年的日子，"
L35_1.m_Talk_TWN = L36_1
L36_1 = "今天真是个具有纪念意义的日子，不是吗？正好是你加入公司的整整一周年呢。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Quite a milestone, isn't it? It's exactly one year since you joined the company."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Quite a milestone, isn't it? It's exactly one year since you joined the company."
L35_1.m_Talk_FRA = L36_1
