L37_1 = "EP14_ACT1_PROLOGUE@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 625
L36_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "RESEARCHER_NPC_NULL_BALE"
L36_1.m_CharStrID = L37_1
L37_1 = "우리가 함께 진행한 프로젝트를 처음으로 발표하는 날이기도 하고!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "私たちみんなで進めたプロジェクトを初めて発表する日でもあるしね！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "And today's the day we unveil our first project together!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "也是我們共同參與的專案第一次正式發表！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "这也是我们第一次发布我们共同进行的项目的日子！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "And today's the day we unveil our first project together!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "And today's the day we unveil our first project together!"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP14_ACT1_PROLOGUE@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 625
L37_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "RESEARCHER_NPC_NULL_BALE"
L37_1.m_CharStrID = L38_1
L38_1 = "밤새 근무하다가 오늘 연차 썼다고 들었어. 생일 파티 준비하고 있었는데 아쉽다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "徹夜明けで有休取ったって聞いたよ。お誕生日パーティーの準備してたのに、残念。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I heard you pulled an all-nighter again. Shame, because I was planning a little party."
L37_1.m_Talk_ENG = L38_1
L38_1 = "聽說你昨晚加班一整夜，今天請假休息。真可惜，本來想今天為你慶生的。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "听说你昨晚值班，今天请了假。真遗憾，我正在准备生日派对呢。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "I heard you pulled an all-nighter again. Shame, because I was planning a little party."
L37_1.m_Talk_DEU = L38_1
L38_1 = "I heard you pulled an all-nighter again. Shame, because I was planning a little party."
L37_1.m_Talk_FRA = L38_1
