L38_1.m_CharStrID = L39_1
L39_1 = "케이크는 숙소 냉장고에 넣어뒀으니까, 생각날 때 꺼내 먹어."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ケーキは部屋の冷蔵庫に入れておいたから、好きな時に食べて。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Anyway, I left the cake in your fridge. Have a slice when you feel like it."
L38_1.m_Talk_ENG = L39_1
L39_1 = "蛋糕放在宿舍冰箱裡，想吃的時候就拿出來吃吧。"
