L2_1 = "EP14_ACT1_PROLOGUE@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 625
L1_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "OFFICER_NPC_NULL_14"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "오늘 발표는 정말 감명 깊었습니다. 이 척박한 세상에 잃어버린 계절을 되찾는 위업을 고작 1년만에 이뤄내시다니 말이에요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "本日の発表、非常に感銘を受けました。この厳しい世の中、失われた季節を取り戻すという偉業をたった1年で成し遂げるなんて……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Your presentation today was truly inspiring. To restore the lost seasons to this barren world in just a year's time is just remarkable."
L1_1.m_Talk_ENG = L2_1
L2_1 = "不過博士今天的發表實在令人震撼。竟然在短短一年內，完成奪回失落季節的霸業！"
L1_1.m_Talk_TWN = L2_1
L2_1 = "今天的发布会真是令人感动。在这个贫瘠的世界中，竟然仅用一年时间就实现了找回失去的季节这一伟业。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Your presentation today was truly inspiring. To restore the lost seasons to this barren world in just a year's time is just remarkable."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Your presentation today was truly inspiring. To restore the lost seasons to this barren world in just a year's time is just remarkable."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
