L4_1 = "SEOSAENG_ATELIER_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "그리고 기상조절시스템은 아직 프로토타입이라 위업이란 표현은 아직 이른 듯 하구려."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "それに、気象調節システムはまだプロトタイプゆえ、偉業と呼ぶにはやや気が早いのではなかろうか。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "And the Weather Control System is still just a prototype. Calling it remarkable is premature."
L3_1.m_Talk_ENG = L4_1
L4_1 = "而且氣象調節系統還只是原型，談不上什麼霸業。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "而且气象调节系统还只是原型，称之为伟业似乎还为时过早。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "And the Weather Control System is still just a prototype. Calling it remarkable is premature."
L3_1.m_Talk_DEU = L4_1
L4_1 = "And the Weather Control System is still just a prototype. Calling it remarkable is premature."
