L5_1 = "OFFICER_NPC_NULL_14"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "하하, 겸손하시긴. 도시관리국이 이번 발표회를 계기로 박사님의 연구에 투자를 결정했잖습니까."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "はは、ご謙遜を。都市管理局もこの発表会を機に、博士の研究に投資を決定したではありませんか。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Haha, ever so humble. But surely you know the City Management has decided to invest in your research because of this presentation."
L4_1.m_Talk_ENG = L5_1
L5_1 = "呵呵，博士你太謙虛了。城市管理局不是已經因為這次發表會，決定投資你的研究嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "哈哈，您真谦虚。城市管理局已经决定借此次发布会契机投资博士您的研究了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Haha, ever so humble. But surely you know the City Management has decided to invest in your research because of this presentation."
L4_1.m_Talk_DEU = L5_1
