L9_1 = "OFFICER_NPC_NULL_14"
L8_1.m_CharStrID = L9_1
L9_1 = "역시 그랬군요. 관리국이라면 서생 박사님의 역량을 일찍이 알아본 거겠죠."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "やはりそうでしたか。管理局はショウ博士のご才覚を早くから見抜いていたのでしょう。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Ah, of course. The Administration surely saw your brilliance long before the rest of us."
L8_1.m_Talk_ENG = L9_1
