L17_1 = "오셨군요, 박사님. 만나 뵙게 되어 영광입니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "博士、お会いできて光栄です。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Ah, Dr. Seosaeng. It's an honor to finally meet you in person."
L16_1.m_Talk_ENG = L17_1
L17_1 = "你來啦，博士。很榮幸見到你。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "哦，您来了，博士。很荣幸见到您。"
