L17_1.m_CharStrID = L18_1
L18_1 = "R_F_C"
L17_1.m_Pos = L18_1
L18_1 = "오늘 발표하신 프로젝트는 정말 인상 깊었어요. 개인적으로도 투자하고 싶더군요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "本日発表されたプロジェクト、とても興味深く拝聴しました。私個人としての投資も考慮したくなるほどでした。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Your presentation today was truly impressive. I must admit, I'd invest myself if I could."
L17_1.m_Talk_ENG = L18_1
L18_1 = "今天的專案發表令人印象深刻，我個人也很想投資呢。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "今天您发布的项目真的很令人印象深刻。我个人也很想投资呢。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Your presentation today was truly impressive. I must admit, I'd invest myself if I could."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Your presentation today was truly impressive. I must admit, I'd invest myself if I could."
