L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "L"
L19_1 = "투자는 경영진과 얘기하는 편이 빠를 거요. 난 권한 없는 일개 연구원일 뿐이니."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "投資の件なら経営陣と話した方が早かろう。某は一介の研究員に過ぎぬゆえ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Best speak to management about that. I'm just a researcher. No authority for such things."
L18_1.m_Talk_ENG = L19_1
L19_1 = "投資的事去找經營層談吧，我只是個沒有決策權的研究員。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "投资还是和管理层谈比较快。我只是个没有权限的普通研究员而已。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Best speak to management about that. I'm just a researcher. No authority for such things."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Best speak to management about that. I'm just a researcher. No authority for such things."
