L20_1 = "제가 박사님을 모신 이유는 따로 있습니다. 몇 가지 전해드릴 것도 있고요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "博士にお越しいただいた理由は別にあります。いくつかお渡ししたい物もありますし。"
