L31_1 = "MS15_04"
L29_1[L30_1] = L31_1
L30_1 = "しかし、なぜその香りと色彩にそれほど惹かれたかは分からない。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Yet why their scent and color draw me so, I can't quite say."
