L36_1 = "준비한 보람이 있었네요. 양이 제법 많다고 생각했는데 전부 드실 줄은 몰랐어요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "用意した甲斐がありました。少し多すぎるかと思いましたが、完食してくださるとは。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I'm glad it suited you. I didn't think you'd finish it all. It was quite a spread."
L35_1.m_Talk_ENG = L36_1
L36_1 = "看來特地準備是值得的。原本還擔心份量太多，沒想到你全吃完了。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "看到你能都吃完我很高兴。我以为量挺多的，没想到你全都吃完了。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "I'm glad it suited you. I didn't think you'd finish it all. It was quite a spread."
L35_1.m_Talk_DEU = L36_1
L36_1 = "I'm glad it suited you. I didn't think you'd finish it all. It was quite a spread."
L35_1.m_Talk_FRA = L36_1
