L37_1 = "確實合我口味，多謝。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "正合我口味，费心了。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Just as you said, it suited my palate. Thank you."
L36_1.m_Talk_DEU = L37_1
