L41_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "직원은 책상 아래에서 묵직해 보이는 가방을 들어 올리더군."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L41_1.m_bTalkCenterFadeIn = true
L42_1 = "職員は机の下から重たそうな鞄を持ち上げた。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "The staff lifted a heavy-looking case from beneath the table."
L41_1.m_Talk_ENG = L42_1
L42_1 = "對方從桌子底下拿出一個沉重的袋子。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "职员从桌子下面提起一个看起来很沉的包。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "The staff lifted a heavy-looking case from beneath the table."
L41_1.m_Talk_DEU = L42_1
L42_1 = "The staff lifted a heavy-looking case from beneath the table."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP14_ACT1_PROLOGUE@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 625
L42_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "돈다발을 보는 건 익숙했다네. 지난 일 년 동안 날 스카우트하려는 기업은 많았으니까."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L42_1.m_bTalkCenterFadeIn = true
L43_1 = "札束は見慣れていた。この一年間、某を引き抜かんとする企業は多かったゆえ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I had grown used to the sight of money as many companies tried to lure me to theirs this past year."
L42_1.m_Talk_ENG = L43_1
L43_1 = "整袋的鈔票我早就見怪不怪，過去一年裡，有多少企業想挖角我。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "我已经习惯看到钱袋子了。过去一年里，有很多公司想要招聘我。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "I had grown used to the sight of money as many companies tried to lure me to theirs this past year."
L42_1.m_Talk_DEU = L43_1
L43_1 = "I had grown used to the sight of money as many companies tried to lure me to theirs this past year."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP14_ACT1_PROLOGUE@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 625
L43_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "내 스스로 그곳을 떠났음에도, 관리국 또한 그들과 별반 다르지 않겠다는 생각을 잠시 했지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L43_1.m_bTalkCenterFadeIn = true
L44_1 = "自らの足で立ち去ったというのに。管理局も彼らと大差ないのだという考えが、鞄を前にして一瞬頭をよぎった。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "So for a moment, I thought the Administration no different from the rest."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我原想，連我自願離開的那個地方，管理局也不例外。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "即使我离开了那里，我也曾认为管理局和他们没有什么不同。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "So for a moment, I thought the Administration no different from the rest."
L43_1.m_Talk_DEU = L44_1
L44_1 = "So for a moment, I thought the Administration no different from the rest."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
