L46_1 = "허나, 가방에 들어있던 건 뜻밖의 것이었어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L45_1.m_bTalkCenterFadeIn = true
L46_1 = "しかし、その鞄に入っていたものは某の考えていたものとは違っていた。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Yet what lay within was something I did not expect."
L45_1.m_Talk_ENG = L46_1
L46_1 = "然而，袋子裡裝的卻是意想不到的東西。"
L45_1.m_Talk_TWN = L46_1
