L49_1 = "그렇습니다. 시니어님의 말씀을 빌리자면, 세상에 하나뿐인 검이라더군요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "はい。シニアの言葉を借りれば、この世にたった一振りしかない剣だそうです。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Indeed. Our Senior says it's one of a kind."
L48_1.m_Talk_ENG = L49_1
L49_1 = "沒錯。照Senior所說，這是世上唯一的一把劍。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "是的。借用资深管理者的话来说，这是世上独一无二的剑。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Indeed. Our Senior says it's one of a kind."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Indeed. Our Senior says it's one of a kind."
L48_1.m_Talk_FRA = L49_1
