L51_1 = "특이한 선물이군. 관리국답게 정교한 기술력이 엿보여."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "変わった土産だな。さすがは管理局だ。精巧な技術力が垣間見える。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "An interesting gift. The craftsmanship is typical of the Administration's handiwork."
L50_1.m_Talk_ENG = L51_1
L51_1 = "真特別的禮物，能看出管理局精湛的工藝。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "真是特别的礼物啊。果然是管理局，能看出精巧的技术力。"
