L4_1 = "박사님께서 직접 만들었던 물건을 돌려드리는 것뿐이니까요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "博士がお作りになったものを、お返しするだけですから。"
