L4_1 = "We are merely returning something you made yourself."
L3_1.m_Talk_ENG = L4_1
L4_1 = "這只是物歸原主，因為這把劍是你親手打造的。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "只是把您亲手制作的东西还给您而已。"
