L10_1 = "난 1년 전 관리국을 떠난 몸이요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "某は1年前に管理局を去った身。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I left the Administration a year ago."
