L11_1 = "EP14_ACT1_PROLOGUE@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 625
