L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "SEOSAENG_ATELIER_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "관리국 보안 절차에 따라 과거의 모든 기록과 그곳에서 겪은 모든 기억을 지웠지."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "管理局のセキュリティポリシーに従い、過去の記録とそこで経験した記憶をすべて末梢した。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "As security protocol demanded, I erased every record and memory of my time there."
L10_1.m_Talk_ENG = L11_1
L11_1 = "並且照管理局的安全程序，將所有過去的紀錄和記憶都消除掉。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "根据管理局的安全程序，过去的所有记录和在那里经历的所有记忆都被抹去了。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "As security protocol demanded, I erased every record and memory of my time there."
L10_1.m_Talk_DEU = L11_1
L11_1 = "As security protocol demanded, I erased every record and memory of my time there."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP14_ACT1_PROLOGUE@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 625
L11_1.m_CutScenStrID = "EP14_ACT1_PROLOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "SEOSAENG_ATELIER_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "그런데, 누구보다 규율에 엄격해야 할 관리자 나리가 내게 과거의 물건을 주라고 했다고?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "なのに、誰よりも規律を厳しく守るべき管理者殿が、某に過去の持ち物を渡すよう指示したと言うのか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "And yet the Administrator himself sends me a piece of the past?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "究竟，最應該遵守規矩的管理者，為何會要你把過去的物品交還給我呢？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "但是，那位应该比任何人都严格遵守规矩的管理者大人居然让你把给过去的东西交给我？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "And yet the Administrator himself sends me a piece of the past?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "And yet the Administrator himself sends me a piece of the past?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
