L30_1 = "RESEARCHER_NPC_NULL_BALE"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "본사가 침식재난으로 망하는 바람에, 그 모델 부품 구하는 게 쉽지 않더라."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "あのモデル、製造元が侵食災害で潰れたせいで部品がなかなか手に入らなくて大変だったよ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Took forever to find parts after the head office tanked in that Corruption disaster."
L29_1.m_Talk_ENG = L30_1
L30_1 = "總公司因為侵蝕災難受到毀損，這型號的零件可不好找。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "由于那款摩托车生产总部被侵蚀灾难摧毁，获取那个零件并不容易。"
L29_1.m_Talk_SCN = L30_1
