L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "됐어. 우리 사이에 수리비는 무슨. 다음부턴 좀 살살 몰아."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "水くさいわね。そんなのいらないわよ。代わりに、これからはもうちょっと優しく使うこと。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Forget it. It's on me. Just take it easy next time."
L31_1.m_Talk_ENG = L32_1
L32_1 = "沒事，我們之間還談什麼錢！以後騎慢點。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "好了。我们之间还谈什么修理费。下次开车悠着点。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Forget it. It's on me. Just take it easy next time."
L31_1.m_Talk_DEU = L32_1
