L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "무장강도 쫓아가는 위험한 짓도 다신 하지 말고."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "武装した強盗を追いかけるような危ない真似は二度としないで。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "And no more chasing down armed robbers, got it?"
L32_1.m_Talk_ENG = L33_1
