L40_1.m_Talk_ENG = L41_1
L41_1 = "哈，你也跟其他人相處一下吧。都來強巴一年了，還是獨來獨往的。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "唉，交点朋友吧。来会议室都一年了，还在说这种话？"
