L45_1.m_bCharPinupEasingTime = 0.3
L46_1 = "아. 내일 보육원에서 진행하는 과학의 날 행사 돕기로 했는데, 혹시 시간 괜찮아?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "そういえば明日、孤児院で科学の日の催しがあって手伝うことになったんだけど、ショウくんも来てくれる？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Oh. Tomorrow's Science Day at the orphanage. Think you can lend a hand?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "對了，明天育幼院有個科學日的活動，你可以幫忙嗎？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "啊。我打算明天去孤儿院帮忙举办科学日活动，你有时间吗？"
