L47_1 = "그러지. 고아들과 어울리는 것도 제법 익숙하니까."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "そうしよう。孤児たちとの付き合いにはもう慣れたしな。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Of course. I'm rather used to spending time with orphans."
L46_1.m_Talk_ENG = L47_1
L47_1 = "可以，我倒是很習慣跟孤兒相處。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "当然了。我已经习惯和孤儿们相处了。"
