L47_1.m_bCharPinup = true
L48_1 = "저기… 이번엔 고아라는 표현 쓰지 말고 제대로 이름으로 불러줘야 한다? 애들은 쉽게 상처받는다고."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "あのね……孤児って言わないで、ちゃんと名前で呼んであげてね。子どもは傷つきやすいの。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Hey… Don't call them \"orphans.\" Use their names, okay? Kids are sensitive."
L47_1.m_Talk_ENG = L48_1
L48_1 = "提醒你一下…這次去別再叫他們孤兒，要直接叫名字，知道嗎？小孩子很敏感的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "那个……这次不要叫他们孤儿，应该用他们的名字来称呼他们。孩子们很容易受伤的。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Hey… Don't call them \"orphans.\" Use their names, okay? Kids are sensitive."
L47_1.m_Talk_DEU = L48_1
