L48_1.m_bCharPinup = true
L49_1 = "그리고 리사한텐 빈말이라도 칭찬 좀 많이 해줘. 서생 씨를 좋아하니까, 분명 기뻐할 거야."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "あと、リサにはお世辞でもいいからたくさん褒め言葉をかけてあげて。あの子はショウくんのこと好きだし、きっと喜ぶと思うんだ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "And tell Lisa she did well even if it's just to make her smile. She adores you."
L48_1.m_Talk_ENG = L49_1
L49_1 = "還有，多稱讚莉莎，就算只是客套話也行。她喜歡你，一定會很高興的。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "而且就算是客套话，也要多夸夸丽莎。她喜欢徐生先生，肯定会很开心的。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "And tell Lisa she did well even if it's just to make her smile. She adores you."
L48_1.m_Talk_DEU = L49_1
