L5_1 = "RESEARCHER_NPC_NULL_BALE"
L4_1.m_CharStrID = L5_1
L5_1 = "난 개인 잔업 때문에 회사에 남아야 할 것 같아. 보육원 혼자 가줄래? 다음에 밥 살게!"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "私、残業のせいで会社にいないといけないの。孤児院には一人で行ってくれない？　後でご飯奢るから！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I've got to stay and wrap up some work. Could you go to the orphanage alone? I'll treat you to lunch next time!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "我臨時有事要在公司加班，育幼院你自己去可以嗎？下次我請你吃飯！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "我因为个人加班可能要留在公司。你能一个人去孤儿院吗？下次请你吃饭！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "I've got to stay and wrap up some work. Could you go to the orphanage alone? I'll treat you to lunch next time!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "I've got to stay and wrap up some work. Could you go to the orphanage alone? I'll treat you to lunch next time!"
L4_1.m_Talk_FRA = L5_1
